'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isSameFloat32Array = require( '@stdlib/assert/is-same-float32array' );
var Float32Array = require( '@stdlib/array/float32' );
var sfillGreaterThan = require( './../lib/sfill_greater_than.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sfillGreaterThan, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
	t.strictEqual( sfillGreaterThan.length, 5, 'has expected arity' );
	t.end();
});

tape( 'the function replaces strided array elements greater than a provided search element', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		0.0,
		2.0,
		0.0,
		4.0,
		-1.0,
		0.0,
		-5.0,
		6.0
	]);
	expected = new Float32Array([
		0.0,
		2.0,
		0.0,
		4.0,
		-1.0,
		0.0,
		-5.0,
		5.0
	]);

	sfillGreaterThan( x.length, 4.0, 5.0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	x = new Float32Array( [ 5.0, 6.0 ] );
	expected = new Float32Array( [ 5.0, 5.0 ] );

	sfillGreaterThan( x.length, 4.0, 5.0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'if no elements are greater than a provided search element, the function returns `x` unchanged', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	expected = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	sfillGreaterThan( x.length, 3.0, 5.0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'if provided a search element equal to `NaN`, the function returns `x` unchanged', function test( t ) {
	var x = new Float32Array( [ NaN, 1.0, NaN ] );

	sfillGreaterThan( x.length, NaN, 5.0, x, 1 );
	t.ok( isnanf( x[ 0 ] ), 'returns expected value' );
	t.strictEqual( x[ 1 ], 1.0, 'returns expected value' );
	t.ok( isnanf( x[ 2 ] ), 'returns expected value' );

	t.end();
});

tape( 'the function does not replace `NaN` elements', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ NaN, 1.0, NaN ] );
	expected = new Float32Array( [ NaN, 5.0, NaN ] );

	sfillGreaterThan( x.length, 0.0, 5.0, x, 1 );
	t.strictEqual( isSameFloat32Array( x, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function considers `-0` and `+0` to be equal', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ -0.0, 1.0, 0.0, -0.0 ] );
	expected = new Float32Array( [ -0.0, 5.0, 0.0, -0.0 ] );

	sfillGreaterThan( x.length, 0.0, 5.0, x, 1 );
	t.strictEqual( isSameFloat32Array( x, expected ), true, 'returns expected value' );

	x = new Float32Array( [ -0.0, 1.0, 0.0, -0.0 ] );
	expected = new Float32Array( [ -0.0, 5.0, 0.0, -0.0 ] );

	sfillGreaterThan( x.length, -0.0, 5.0, x, 1 );
	t.strictEqual( isSameFloat32Array( x, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a reference to the input array', function test( t ) {
	var out;
	var x;

	x = new Float32Array( [ 1.0, 0.0, 3.0, 0.0, 5.0 ] );
	out = sfillGreaterThan( x.length, 4.0, 5.0, x, 1 );

	t.strictEqual( out, x, 'same reference' );
	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `x` unchanged', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ 0.0, -4.0, 1.0 ] );
	expected = new Float32Array( [ 0.0, -4.0, 1.0 ] );

	sfillGreaterThan( 0, 4.0, 5.0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	x = new Float32Array( [ 0.0, -4.0, 1.0 ] );
	sfillGreaterThan( -4, 4.0, 5.0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying an `x` stride', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		8.0,  // 0
		-3.0,
		7.0,  // 1
		3.0,
		6.0   // 2
	]);
	expected = new Float32Array([
		5.0,  // 0
		-3.0,
		5.0,  // 1
		3.0,
		5.0   // 2
	]);

	sfillGreaterThan( 3, 4.0, 5.0, x, 2 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a negative `x` stride', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		8.0,  // 2
		-3.0,
		7.0,  // 1
		3.0,
		6.0   // 0
	]);
	expected = new Float32Array([
		5.0,  // 2
		-3.0,
		5.0,  // 1
		3.0,
		5.0   // 0
	]);

	sfillGreaterThan( 3, 4.0, 5.0, x, -2 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var x0;
	var x1;

	x0 = new Float32Array([
		1.0,
		8.0,  // 0
		3.0,
		6.0,  // 1
		4.0,
		0.0   // 2
	]);
	expected = new Float32Array([
		1.0,
		5.0,  // 0
		3.0,
		5.0,  // 1
		4.0,
		0.0   // 2
	]);

	x1 = new Float32Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	sfillGreaterThan( 3, 4.0, 5.0, x1, 2 );
	t.deepEqual( x0, expected, 'returns expected value' );

	t.end();
});
